  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Praziquantel showed absolute oral bioavailability of 27.2±5.4% even in patients with hepatic impairment, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pethidine absolute oral bioavailability in healthy subjects was 0.52 (0.47–0.61), well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Solifenacin absolute oral bioavailability was 88% in healthy volunteers, demonstrating high oral absorption for a nitrogen-containing heterocyclic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Encainide, despite substantial first-pass metabolism, still showed oral bioavailability of 20–30% in healthy subjects, at or above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tolfenamic acid absolute oral bioavailability was 63.2% in healthy female volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Neotame, a methyl-ester-containing compound, was at least 34.4% systemically available in humans, showing that ester-containing drugs can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Delapril, an ester prodrug ACE inhibitor, had oral bioavailability >55% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Benazepril, another ester prodrug ACE inhibitor, had oral bioavailability >37% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is clopidogrel, a thienopyridine antiplatelet prodrug. All highly transferable experimental analogues show absolute oral bioavailability above 20%, including ester prodrugs and drugs with first-pass metabolism. The evidence consistently supports a high F ≥20% prediction.",
  "evidence_gaps": [
    "No direct clopidogrel-specific absolute bioavailability record is present in the supplied evidence; the prediction relies on highly transferable analogues.",
    "First-pass ester hydrolysis of the methyl ester is not directly measured for the query, but ester-containing analogues still show F >20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

